nextflow_process {

    name "Test Process CLEANIFIER_FILTER"
    tag "modules"
    tag "modules_nfcore"
    tag "cleanifier"
    tag "cleanifier/index"
    tag "cleanifier/filter"

    script "../main.nf"
    process "CLEANIFIER_FILTER"

    config "./nextflow.config"

    setup {
        run("CLEANIFIER_INDEX") {
            script "../../index/main.nf"
            params {
                module_args = '-k 31'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[1] = 100000
                """
            }
        }
    }

    test("sarscov2 - [fastq.gz, fastq.gz] - paired_end") {
        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = CLEANIFIER_INDEX.out.index.join(CLEANIFIER_INDEX.out.info)
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("sarscov2 - [fastq.gz] - single_end") {
        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = CLEANIFIER_INDEX.out.index.join(CLEANIFIER_INDEX.out.info)
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("sarscov2 - [fastq.gz, fastq.gz] - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = CLEANIFIER_INDEX.out.index.join(CLEANIFIER_INDEX.out.info)
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("sarscov2 - [fastq.gz] - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = CLEANIFIER_INDEX.out.index.join(CLEANIFIER_INDEX.out.info)
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}

